def ampliar_zonas(apps, schema_editor):
    Zona = apps.get_model('ordenes', 'ZonaOficinaIA')
    db = schema_editor.connection.alias
    iniciales = [
        ('Gerencia', 'gerencia', 'Dirección, estrategia y resultados', 'Finanzas y equipo'),
        ('Oficina', 'oficina', 'Administración, compras y operación', 'Compras y entregas'),
        ('Área comercial', 'showroom', 'Ventas, clientes y crecimiento', 'Showroom comercial'),
        ('Tecnología', 'tecnologia', 'Herramientas, infraestructura e inteligencia artificial', None),
        ('Desarrollo creativo', 'creativo', 'Diseño, contenidos y nuevas ideas', 'Estudio LOTTUS'),
        ('Zona social', 'social', 'Encuentro y descanso del equipo', None),
    ]
    usadas = set()
    for orden, (nombre, ambiente, descripcion, anterior) in enumerate(iniciales):
        zona = Zona.objects.using(db).filter(nombre__iexact=nombre).first()
        if not zona and anterior:
            zona = Zona.objects.using(db).filter(nombre=anterior).first()
        if zona:
            # Mantiene la identidad y los agentes; conserva descripciones personalizadas.
            zona.nombre = nombre
            zona.ambiente = ambiente
            zona.orden = orden
            zona.save(using=db, update_fields=['nombre', 'ambiente', 'orden'])
        else:
            zona = Zona.objects.using(db).create(nombre=nombre, ambiente=ambiente, descripcion=descripcion, orden=orden)
        usadas.add(zona.pk)
    # Las zonas personalizadas no desaparecen ni pierden sus perfiles.
    for orden, zona in enumerate(Zona.objects.using(db).exclude(pk__in=usadas).order_by('orden', 'id'), start=6):
        zona.orden = orden
        zona.save(using=db, update_fields=['orden'])


